def pairing_function(x, y):
    s = x + y
    min_xy = min(x, y)
    # S(s) = s * (s + 1) // 2
    return s * (s + 1) // 2 + min_xy

count_odd = 0
limit = 100

for x in range(limit):
    for y in range(limit):
        value = pairing_function(x, y)
        if value % 2 != 0:
            count_odd += 1

print(count_odd)

